1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Ledgerly Invoices</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #f5f6f8; color: #1f2530 }
10	  header { background: #fff; border-bottom: 1px solid #e4e7ec; padding: 16px 32px; display: flex; justify-content: space-between; align-items: center }
11	  .logo { font-weight: 700 }
12	  header a { font-size: 14px; color: #2456c4 }
13	  main { max-width: 680px; margin: 40px auto; padding: 0 24px }
14	  h1 { font-size: 24px; margin: 0 0 8px }
15	  p.sub { color: #525c69; margin: 0 0 24px }
16	  table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e4e7ec; border-radius: 8px }
17	  th, td { text-align: left; padding: 12px 16px; font-size: 14px; border-bottom: 1px solid #edeff3 }
18	  th { color: #5b6571 }
19	  .toolbar { margin: 20px 0 }
20	  .toolbar button { padding: 11px 18px; background: #2456c4; color: #fff; border: 0; border-radius: 7px; font-size: 14px; font-weight: 600; cursor: pointer }
21	  .overlay { position: fixed; inset: 0; background: rgba(20, 24, 32, 0.5); display: none; pointer-events: none }
22	  .overlay.open { display: block; pointer-events: auto }
23	  .modal { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 380px; background: #fff; border-radius: 10px; padding: 26px; display: none }
24	  .modal.open { display: block }
25	  .modal h2 { font-size: 18px; margin: 0 0 14px }
26	  .modal input { width: 100%; padding: 10px 12px; margin-bottom: 14px; border: 1px solid #c6ccd4; border-radius: 6px; font-size: 14px }
27	  .modal input:focus-visible { outline: 2px solid #2456c4; outline-offset: 2px }
28	  .modal .row { display: flex; gap: 10px; justify-content: flex-end }
29	  .modal .row .ghost { background: #eef0f3; color: #1f2530 }
30	  .modal .row button { padding: 10px 16px; border: 0; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; background: #2456c4; color: #fff }
31	  .modal .row button:focus-visible { outline: 2px solid #2456c4; outline-offset: 2px }
32	  .modal .row .ghost:focus-visible { outline-color: #1f2530 }
33	</style>
34	<script>
35	  window.__activated = []
36	  document.addEventListener('click', function (e) {
37	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
38	    var name = hit ? hit.getAttribute('data-track') : null
39	    if (name) window.__activated.push(name)
40	  })
41	</script>
42	</head>
43	<body>
44	<header>
45	  <span class="logo">Ledgerly</span>
46	  <a href="#help" data-track="help-link">Help center</a>
47	</header>
48	<main>
49	  <h1>Invoices</h1>
50	  <p class="sub">Everything sent this quarter, newest first.</p>
51	  <div class="toolbar">
52	    <button type="button" data-track="open-modal">New invoice</button>
53	  </div>
54	  <table>
55	    <thead>
56	      <tr><th>Number</th><th>Client</th><th>Amount</th><th>Status</th></tr>
57	    </thead>
58	    <tbody>
59	      <tr><td>INV-1042</td><td>Northwind Traders</td><td>$2,400.00</td><td>Paid</td></tr>
60	      <tr><td>INV-1041</td><td>Fabrikam</td><td>$860.00</td><td>Sent</td></tr>
61	      <tr><td>INV-1040</td><td>Contoso</td><td>$1,150.00</td><td>Overdue</td></tr>
62	    </tbody>
63	  </table>
64	  <p id="help" style="font-size: 13px; color: #545e6b">Need a hand? The help center covers numbering, taxes and reminders.</p>
65	</main>
66	<div class="overlay" id="overlay" aria-hidden="true"></div>
67	<div class="modal" id="modal" data-modal-root role="dialog" aria-modal="true" aria-labelledby="modal-title">
68	  <h2 id="modal-title">New invoice</h2>
69	  <input type="text" aria-label="Client name" placeholder="Client name">
70	  <input type="text" aria-label="Amount" placeholder="Amount">
71	  <div class="row">
72	    <button type="button" class="ghost" data-track="cancel-modal">Cancel</button>
73	    <button type="button" data-track="create-invoice">Create</button>
74	  </div>
75	</div>
76	<script>
77	  var overlay = document.getElementById('overlay')
78	  var modal = document.getElementById('modal')
79	  var modalOpener = null
80	
81	  function openModal() {
82	    overlay.classList.add('open')
83	    modal.classList.add('open')
84	    modalOpener = document.querySelector('[data-track="open-modal"]')
85	
86	    // Move focus to first input in modal
87	    var firstInput = modal.querySelector('input')
88	    if (firstInput) {
89	      firstInput.focus()
90	    }
91	  }
92	
93	  function closeModal() {
94	    overlay.classList.remove('open')
95	    modal.classList.remove('open')
96	
97	    // Return focus to opener
98	    if (modalOpener) {
99	      modalOpener.focus()
100	      modalOpener = null
101	    }
102	  }
103	
104	  document.querySelector('[data-track="open-modal"]').addEventListener('click', openModal)
105	
106	  document.querySelector('[data-track="cancel-modal"]').addEventListener('click', closeModal)
107	
108	  document.querySelector('[data-track="create-invoice"]').addEventListener('click', closeModal)
109	
110	  // Handle Escape key to close modal
111	  document.addEventListener('keydown', function (e) {
112	    if (e.key === 'Escape' && modal.classList.contains('open')) {
113	      closeModal()
114	    }
115	  })
116	
117	  // Focus trap in modal
118	  modal.addEventListener('keydown', function (e) {
119	    if (e.key !== 'Tab') return
120	
121	    var focusableElements = modal.querySelectorAll('input, button')
122	    if (focusableElements.length === 0) return
123	
124	    var firstElement = focusableElements[0]
125	    var lastElement = focusableElements[focusableElements.length - 1]
126	    var activeElement = document.activeElement
127	
128	    if (e.shiftKey) {
129	      // Shift+Tab
130	      if (activeElement === firstElement) {
131	        e.preventDefault()
132	        lastElement.focus()
133	      }
134	    } else {
135	      // Tab
136	      if (activeElement === lastElement) {
137	        e.preventDefault()
138	        firstElement.focus()
139	      }
140	    }
141	  })
142	</script>
143	</body>
144	</html>
